Set error = {}

If obj.%Get("User") = "" {
	set ^webService("ValidateJSONForDisplayColumns") = "User was blank"
	Set error.errormessage = "User was blank"
	Quit 0
}	

set ^webService("ValidateJSONForDisplayColumns") = "ValidateJSONForDisplayColumns: " _ obj.%Get("User")
Quit 1

	set ^webService("CopyDisplayColumnsFromJSON User: ") = obj.User
	set deleteRows = 1

	set iter = obj.displayColumns.%GetIterator()

    while iter.%GetNext(.key , .value ) {
	    if ( (value.TransactionCode '= "") && (value.key '= "" ))
	    {
		  	set cm = ##class(IHC.ITF.ITFCOMMON.X12.DisplayColumns).%New()
			Set cm.User=obj.User
			set cm.TransactionCode = value.TransactionCode
			Set cm.Key = value.key
			set cm.Order = value.Order	
			set cm.LastmodDtTM = $ZDATETIME($HOROLOG,3, 1)
			if (deleteRows = 1)
			{
					Set rs = ##class(%SQL.Statement).%ExecDirect(,"DELETE IHC_ITF_ITFCOMMON_X12.DisplayColumns where user = '" _ obj.User _ "' AND TransactionCode = '" _value.TransactionCode _ "'")
					Set deleteRows = 0
			}

			Set sc = cm.%Save()
			do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
			if ($$$ISOK(sc)) {
				set ^webService("CopyDisplayColumnsFromJSON Added") = cm.%Id()	
				do result.%Set("id", cm.%Id())
			}
			else
			{
				set ^webService("CopyDisplayColumnsFromJSON Error") = sc
				QUIT
			}
	    }

    }

Set ok = 1
Try {
	Set obj = ##class(%DynamicObject).%FromJSON(%request.Content)
	set ^webService("GetJSONFromRequest ") = obj
} Catch ex {
	Set ok = 0
}
Quit ok

     set ^webService("GetRelatedTransaction Start") = GroupControlNumber _ ", " _ transType _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set id1=InterchangeSenderID, id2=InterchangeReceiverID

    if (transType [ "837") // 837 I,P,D
    {	    
	    set transType = "837"
    }
    elseif (transType [ "005010X222") // 837 from 999
    {
	    set id2=InterchangeSenderID, id1=InterchangeReceiverID
	    set transType = "837"
    }
    elseif (transType [ "005010X279") // 270 from 999
    {
	    set id2=InterchangeSenderID, id1=InterchangeReceiverID
	    set transType = "270"
    }
    elseif (transType [ "005010X221") // 835 from 999
    {
	    set id2=InterchangeSenderID, id1=InterchangeReceiverID
	    set transType = "835"
    }


	set tStatement = ##class(%SQL.Statement).%New()
	SET x12query = 5
	SET x12query(1) = "select cl.InterchangeSenderID, cl.InterchangeReceiverID, cl.InterchangeControlNumber, ack.FileName, ack.x12Data as ST, ack2.x12Data as X999, cl.x12Data as tranX12"
	SET x12query(2) = " from  IHC_X12.Data" _ transType _" cl,  IHC_X12.Data999 ack, IHC_X12.Data999 ack2 "
	SET x12query(3) = " where ack.AK1GroupControlNumber = cl.GroupControlNumber "
	SET x12query(4) = " and ack.X12DataParentId = ack2.ID and ack.AK1VersionReleaseIndustryIdenti = cl.VersionReleaseIndustryIdenti "
	SET x12query(5) = " and cl.GroupControlNumber = ? and cl.InterchangeSenderID = ? and cl.InterchangeReceiverID = ?"
    set tStatus = tStatement.%Prepare(.x12query)
    if $$$ISERR(tStatus)
    {
	    Do ..%SetStatusCode(200)
	   Do tArr.%Push({
				"Operation":"GetRelatedTransaction",
				"Error": (tStatus)})

    }
    else
    {
	    SET rs=tStatement.%Execute(GroupControlNumber, id1, id2 )

	    set ^webService("GetRelatedTransaction rs") = "rs " _rs.%SQLCODE _ ", " _ $ZDATETIME($HOROLOG,3, 1)
		While rs.%Next() {

				set ^webService("ImplementationAcknowledgment While") = rs.%ROWCOUNT _ ", Next " _ $ZDATETIME($HOROLOG,3, 1)
				Do tArr.%Push({
					"Operation":"GetRelatedTransaction",
					"InterchangeSenderID": (rs.%Get("InterchangeSenderID")),
					"InterchangeReceiverID": (rs.%Get("InterchangeReceiverID")),
					"FileName": (rs.%Get("FileName")),
					"InterchangeControlNumber": (rs.%Get("InterchangeControlNumber")),				
					"x12Data": (rs.%Get("X999")),
					"StX12Data": (rs.%Get("ST")),
					"tranX12": (rs.%Get("tranX12"))			
				})

		}
		set ^webService("GetRelatedTransaction") = "End: " _ $ZDATETIME($HOROLOG,3, 1)
		Do ..%SetStatusCode(200)
    }
	return tArr

 set ^webService("GetRelatedEligBenefit Start") = transType _" = "_ C1TRN1RefId _ "/"_ D1TRN1RefId _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set tRN1RefId = ""
    set tStatement = ##class(%SQL.Statement).%New()
	SET x12query = 11
	SET x12query(1) = "select req.loop2000C1TRN1RefId as ReqCRef, req.loop2000D1TRN1RefId as ReqDRef,"
	SET x12query(2) = "res.loop2000C1TRN1RefId as RespCRef, res.loop2000D1TRN1RefId as RespDRef,"
	SET x12query(3) = "req.loop2100CNM1NameLastorOrganizationName ||', ' || req.loop2100CNM1NameFirst as ReqSubNm,"
	SET x12query(4) = "req.loop2100DNM1NameLastorOrganizationName||', ' || req.loop2100DNM1NameFirst as ReqDepNm,"
	SET x12query(5) = "res.loop2100CNM1NameLastorOrganizationName||', ' || res.loop2100CNM1NameFirst as RespSubNm,"
	SET x12query(6) = "res.loop2100DNM1NameLastorOrganizationName||', ' || res.loop2100DNM1NameFirst as RespDepNm,"
	SET x12query(7) = "req.x12Data as ReqX12, res.x12Data as ResX12, req.FileName as reqFileName, res.FileName as resFileName"

	SET x12query(8) = " from IHC_X12.Data270 req, IHC_X12.Data271 res where "
	SET x12query(9) = " (req.loop2000C1TRN1RefId = res.loop2000C1TRN1RefId OR req.loop2000D1TRN1RefId =  res.loop2000D1TRN1RefId)"
	if (transType = "270")
	{
		SET x12query(11) = " and req.InterchangeControlNumber = ? and req.InterchangeSenderID = ? and req.InterchangeReceiverID = ?"

		if (C1TRN1RefId '= "")
		{
			SET x12query(10) = " and req.loop2000C1TRN1RefId = ?"
			set tRN1RefId = C1TRN1RefId
		}
		else
		{
			SET x12query(10) = " and req.loop2000D1TRN1RefId = ?"
			set tRN1RefId = D1TRN1RefId
		}
	}
	else
	{
		SET x12query(11) = " and res.InterchangeControlNumber = ? and res.InterchangeSenderID = ? and res.InterchangeReceiverID = ?"

		if (C1TRN1RefId '= "")
		{
			SET x12query(10) = " and res.loop2000C1TRN1RefId = ?"
			set tRN1RefId = C1TRN1RefId
		}
		else
		{
			SET x12query(10) = " and res.loop2000D1TRN1RefId = ?"
			set tRN1RefId = D1TRN1RefId
		}

	}

    set tStatus = tStatement.%Prepare(.x12query)
    if $$$ISERR(tStatus)
    {
	    Do ..%SetStatusCode(200)
	    Do tArr.%Push({
				"Operation":"GetRelatedTransaction",
				"Error": (tStatus)})

    }
    else
    {
   	    set ^webService("GetRelatedEligBenefit SQL") = x12query(10) _ x12query(11)
	    set ^webService("GetRelatedEligBenefit Val") = tRN1RefId _ ", " _InterchangeControlNumber _ ", " _ InterchangeSenderID _ ", " _ InterchangeReceiverID
	    set ^webService("GetRelatedEligBenefit While, RespCRef") = ""

	    SET rs=tStatement.%Execute(tRN1RefId, InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID )

		While rs.%Next() {

				set ^webService("GetRelated27x While, RespCRef") = rs.%Get("ReqX12") _ ", Next " _ $ZDATETIME($HOROLOG,3, 1)
				Do tArr.%Push({
					"Operation":"GetRelated27x",
					"ReqCRef": (rs.%Get("ReqCRef")),
					"ReqDRef": (rs.%Get("ReqDRef")),
					"RespCRef": (rs.%Get("RespCRef")),
					"RespDRef": (rs.%Get("RespDRef")),
					"ReqSubNm": (rs.%Get("ReqSubNm")),				
					"ReqDepNm": (rs.%Get("ReqDepNm")),
					"RespSubNm": (rs.%Get("RespSubNm")),
					"RespDepNm": (rs.%Get("RespDepNm")),
					"ReqX12": (rs.%Get("ReqX12")),
					"ResX12": (rs.%Get("ResX12")),
					"ReqFileName": (rs.%Get("reqFileName")),
					"ResFileName": (rs.%Get("resFileName"))			
				})
				set ^webService("GetRelatedEligBenefit While") = "Pushed" _ ", " _ $ZDATETIME($HOROLOG,3, 1)
				QUIT

		}
		set ^webService("GetRelatedEligBenefit") = "End: " _ tArr.%Size() _ " at " _ $ZDATETIME($HOROLOG,3, 1)
		Do ..%SetStatusCode(200)
    }
	return tArr

 set ^webService("GetRelatedClaimStatus Start") = transType _" = "_ C1TRN1RefId _ "/"_ D1TRN1RefId _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ " @"_ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set tRN1RefId = ""
    set tStatement = ##class(%SQL.Statement).%New()
	SET x12query = 9
	SET x12query(1) = "select req.loop2200D1TRNRefId as ReqDRef, req.loop2200E1TRNRefId as ReqERef,"
	SET x12query(2) = "res.loop2200D1TRNRefId as ResDRef, res.loop2200E1TRNRefId as ResERef,"
	SET x12query(3) = "req.loop2100DNM1NameLastorOrganizationName||', ' || req.loop2100DNM1NameFirst as ReqDepNm,"
	SET x12query(4) = "res.loop2100DNM1NameLastorOrganizationName||', ' || res.loop2100DNM1NameFirst as ResDepNm,"
	SET x12query(5) = "req.x12Data as ReqX12, res.x12Data as ResX12, req.FileName as reqFileName, res.FileName as resFileName"

	SET x12query(6) = " from IHC_X12.Data276 req, IHC_X12.Data277 res where "
	SET x12query(7) = " (req.loop2200D1TRNRefId = res.loop2200D1TRNRefId)"
	if (transType = "276")
	{
		SET x12query(9) = " and req.InterchangeControlNumber = ? and req.InterchangeSenderID = ? and req.InterchangeReceiverID = ?"

		if ( (C1TRN1RefId '= "") || (C1TRN1RefId '= "undefined"))
		{
			SET x12query(8) = " and req.loop2200D1TRNRefId = ?"
			set tRN1RefId = C1TRN1RefId
		}
		else
		{
			SET x12query(8) = " and req.loop2200E1TRNRefId = ?"
			set tRN1RefId = D1TRN1RefId
		}

	}
	else
	{
		SET x12query(9) = " and res.InterchangeControlNumber = ? and res.InterchangeSenderID = ? and res.InterchangeReceiverID = ?"

		if ( (C1TRN1RefId '= "") || (C1TRN1RefId '= "undefined"))
		{
			SET x12query(8) = " and res.loop2200D1TRNRefId = ?"
			set tRN1RefId = C1TRN1RefId
		}
		else
		{
			SET x12query(8) = " and res.loop2200E1TRNRefId = ?"
			set tRN1RefId = D1TRN1RefId
		}


	}
	set ^webService("GetRelatedClaimStatus SQL") = x12query(8) _ x12query(9)

    set tStatus = tStatement.%Prepare(.x12query)
    if $$$ISERR(tStatus)
    {
	    Do ..%SetStatusCode(200)
	   Do tArr.%Push({
				"Operation":"GetRelatedTransaction",
				"Error": (tStatus)})

    }
    else
    {
	    SET rs=tStatement.%Execute(tRN1RefId, InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID )

	    set ^webService("GetRelatedClaimStatus rs") = "Id: " _ tRN1RefId _ ", CODE: " _rs.%SQLCODE _ ", " _ $ZDATETIME($HOROLOG,3, 1)
		While rs.%Next() {

				set ^webService("GetRelatedClaimStatus While") = rs.%ROWCOUNT _ ", Next " _ $ZDATETIME($HOROLOG,3, 1)
				Do tArr.%Push({
					"Operation":"GetRelatedClaimStatus",				
					"ReqDRef": (rs.%Get("ReqDRef")),				
					"ResDRef": (rs.%Get("ResDRef")),
					"ReqERef": (rs.%Get("ReqERef")),				
					"ResERef": (rs.%Get("ResERef")),			
					"ReqDepNm": (rs.%Get("ReqDepNm")),
					"ResDepNm": (rs.%Get("ResDepNm")),
					"ReqX12": (rs.%Get("ReqX12")),
					"ResX12": (rs.%Get("ResX12")),
					"ReqFileName": (rs.%Get("reqFileName")),
					"ResFileName": (rs.%Get("resFileName"))			

				})
				set ^webService("GetRelatedClaimStatus While Push ") = (rs.%Get("ResDepNm"))

		}
		set ^webService("GetRelatedClaimStatus") = "End: " _ tArr.%Size() _ " at " _ $ZDATETIME($HOROLOG,3, 1)
